// WorkspaceHandleIdEvent : workspace id
//
// If this event is emitted, it will be send immediately after the
// ext_workspace_handle_v1 is created or when an id is assigned to
// a workspace (at most once during its lifetime).
//
// An id will never change during the lifetime of the `ext_workspace_handle_v1`
// and is guaranteed to be unique during its lifetime.
//
// Ids are not human-readable and shouldn't be displayed, use `name` for that purpose.
//
// Compositors are expected to only send ids for workspaces likely stable across multiple
// sessions and can be used by clients to store preferences for workspaces. Workspaces without
// ids should be considered temporary and any data associated with them should be deleted once
// the respective object is lost.
type WorkspaceHandleIdEvent struct {
	Id string
}
type WorkspaceHandleIdHandlerFunc func(WorkspaceHandleIdEvent)

// SetIdHandler : sets handler for WorkspaceHandleIdEvent
func (i *WorkspaceHandle) SetIdHandler(f WorkspaceHandleIdHandlerFunc) {
	i.idHandler = f
}

// WorkspaceHandleNameEvent : workspace name changed
//
// This event is emitted immediately after the ext_workspace_handle_v1 is
// created and whenever the name of the workspace changes.
//
// A name is meant to be human-readable and can be displayed to a user.
// Unlike the id it is neither stable nor unique.
type WorkspaceHandleNameEvent struct {
	Name string
}
type WorkspaceHandleNameHandlerFunc func(WorkspaceHandleNameEvent)

// SetNameHandler : sets handler for WorkspaceHandleNameEvent
func (i *WorkspaceHandle) SetNameHandler(f WorkspaceHandleNameHandlerFunc) {
	i.nameHandler = f
}

// WorkspaceHandleCoordinatesEvent : workspace coordinates changed
//
// This event is used to organize workspaces into an N-dimensional grid
// within a workspace group, and if supported, is emitted immediately after
// the ext_workspace_handle_v1 is created and whenever the coordinates of
// the workspace change. Compositors may not send this event if they do not
// conceptually arrange workspaces in this way. If compositors simply
// number workspaces, without any geometric interpretation, they may send
// 1D coordinates, which clients should not interpret as implying any
// geometry. Sending an empty array means that the compositor no longer
// orders the workspace geometrically.
//
// Coordinates have an arbitrary number of dimensions N with an uint32
// position along each dimension. By convention if N > 1, the first
// dimension is X, the second Y, the third Z, and so on. The compositor may
// chose to utilize these events for a more novel workspace layout
// convention, however. No guarantee is made about the grid being filled or
// bounded; there may be a workspace at coordinate 1 and another at
// coordinate 1000 and none in between. Within a workspace group, however,
// workspaces must have unique coordinates of equal dimensionality.
type WorkspaceHandleCoordinatesEvent struct {
	Coordinates []byte
}
type WorkspaceHandleCoordinatesHandlerFunc func(WorkspaceHandleCoordinatesEvent)

// SetCoordinatesHandler : sets handler for WorkspaceHandleCoordinatesEvent
func (i *WorkspaceHandle) SetCoordinatesHandler(f WorkspaceHandleCoordinatesHandlerFunc) {
	i.coordinatesHandler = f
}

// WorkspaceHandleStateEvent : the state of the workspace changed
//
// This event is emitted immediately after the ext_workspace_handle_v1 is
// created and each time the workspace state changes, either because of a
// compositor action or because of a request in this protocol.
//
// Missing states convey the opposite meaning, e.g. an unset active bit
// means the workspace is currently inactive.
type WorkspaceHandleStateEvent struct {
	State uint32
}
type WorkspaceHandleStateHandlerFunc func(WorkspaceHandleStateEvent)

// SetStateHandler : sets handler for WorkspaceHandleStateEvent
func (i *WorkspaceHandle) SetStateHandler(f WorkspaceHandleStateHandlerFunc) {
	i.stateHandler = f
}

// WorkspaceHandleCapabilitiesEvent : compositor capabilities
//
// This event advertises the capabilities supported by the compositor. If
// a capability isn't supported, clients should hide or disable the UI
// elements that expose this functionality. For instance, if the
// compositor doesn't advertise support for removing workspaces, a button
// triggering the remove request should not be displayed.
//
// The compositor will ignore requests it doesn't support. For instance,
// a compositor which doesn't advertise support for remove will ignore
// remove requests.
//
// Compositors must send this event once after creation of an
// ext_workspace_handle_v1 . When the capabilities change, compositors
// must send this event again.
type WorkspaceHandleCapabilitiesEvent struct {
	Capabilities uint32
}
type WorkspaceHandleCapabilitiesHandlerFunc func(WorkspaceHandleCapabilitiesEvent)

// SetCapabilitiesHandler : sets handler for WorkspaceHandleCapabilitiesEvent
func (i *WorkspaceHandle) SetCapabilitiesHandler(f WorkspaceHandleCapabilitiesHandlerFunc) {
	i.capabilitiesHandler = f
}

// WorkspaceHandleRemovedEvent : this workspace has been removed
//
// This event is send when the workspace associated with the ext_workspace_handle_v1
// has been removed. After sending this request, the compositor will immediately consider
// the object inert. Any requests will be ignored except the destroy request.
//
// It is guaranteed there won't be any more events referencing this
// ext_workspace_handle_v1.
//
// The compositor must only remove a workspaces not currently belonging to any
// workspace_group.
type WorkspaceHandleRemovedEvent struct{}
type WorkspaceHandleRemovedHandlerFunc func(WorkspaceHandleRemovedEvent)

// SetRemovedHandler : sets handler for WorkspaceHandleRemovedEvent
func (i *WorkspaceHandle) SetRemovedHandler(f WorkspaceHandleRemovedHandlerFunc) {
	i.removedHandler = f
}

// FdEvents reports the events that carry a file descriptor (bit n = opcode n).
func (i *WorkspaceHandle) FdEvents() uint64 {
	return 0x0
}

func (i *WorkspaceHandle) Dispatch(opcode uint32, fd int, data []byte) {
	switch opcode {
	case 0:
		if i.idHandler == nil {
			return
		}
		var e WorkspaceHandleIdEvent
		l := 0
		idLen := client.PaddedLen(int(client.Uint32(data[l : l+4])))
		l += 4
		e.Id = client.String(data[l : l+idLen])
		l += idLen

		i.idHandler(e)
	case 1:
		if i.nameHandler == nil {
			return
		}
		var e WorkspaceHandleNameEvent
		l := 0
		nameLen := client.PaddedLen(int(client.Uint32(data[l : l+4])))
		l += 4
		e.Name = client.String(data[l : l+nameLen])
		l += nameLen

		i.nameHandler(e)
	case 2:
		if i.coordinatesHandler == nil {
			return
		}
		var e WorkspaceHandleCoordinatesEvent
		l := 0
		coordinatesLen := int(client.Uint32(data[l : l+4]))
		l += 4
		e.Coordinates = make([]byte, coordinatesLen)
		copy(e.Coordinates, data[l:l+coordinatesLen])
		l += client.PaddedLen(coordinatesLen)

		i.coordinatesHandler(e)
	case 3:
		if i.stateHandler == nil {
			return
		}
		var e WorkspaceHandleStateEvent
		l := 0
		e.State = client.Uint32(data[l : l+4])
		l += 4

		i.stateHandler(e)
	case 4:
		if i.capabilitiesHandler == nil {
			return
		}
		var e WorkspaceHandleCapabilitiesEvent
		l := 0
		e.Capabilities = client.Uint32(data[l : l+4])
		l += 4

		i.capabilitiesHandler(e)
	case 5:
		if i.removedHandler == nil {
			return
		}
		var e WorkspaceHandleRemovedEvent

		i.removedHandler(e)
	}
}
